# 🪞 Mirrormancer
# Try to make mirror columns. A column is a mirror if its numbers read the same forwards and
# backwards. Each mirror column scores 1 primary point. Each matching pair (first and last, second
# and second-last, and so on) in any column scores 1 secondary point.

def utility(grid):
    mirrors = 0
    pairs = 0
    for line in grid.columns:
        half = len(line) // 2
        matches = 0
        for i in range(half):
            if line[i].value == line[len(line) - 1 - i].value:
                matches += 1
        pairs += matches
        if matches == half:
            mirrors += 1
    return (mirrors, pairs)

def agent(grid):
    c = [Cell() for x in grid.cells]
    for y, x in zip(c, grid.cells):
        y.row, y.col, y.value = x.row, x.col, x.value
    for y in c:
        i = 4 * y.row + y.col
        y.right = c[i + 1] if y.col < 3 else None
        y.down = c[i + 4] if y.row < 3 else None
    board = Grid([c[i:i + 4] for i in (0, 4, 8, 12)])
    best, move = utility(board), []
    for y in c:
        old = y.value
        for y.value in range(10):
            u = utility(board)
            if u > best:
                best, move = u, [write(y, y.value)]
        y.value = old
    return move

