# 👋 Strangers
# Try to make touching numbers in the same corner box strangers. Two numbers are strangers when no
# number bigger than 1 divides both and they are not next to each other when counting. So 4 and 9
# are strangers; 4 and 6 share 2; 4 and 5 are next-door. Each pair of strangers scores 1 primary
# point when both are bigger than 1. Each 1 scores 1 secondary point for every bigger number it
# touches in its box.

def shared(a, b):
    # The biggest number that divides both.
    return a if b == 0 else shared(b, a % b)

def utility(grid):
    pairs = 0
    ones = 0
    for line in grid.rows + grid.columns:
        # The touching pairs inside the boxes: cells 1 and 2, 3 and 4, and so on.
        for k in range(0, len(line), 2):
            a = line[k].value
            b = line[k + 1].value
            if a * b < 2 or shared(a, b) > 1:
                continue  # A 0, two 1s, or a shared divisor.
            if a == 1 or b == 1:
                ones += 1
            elif abs(a - b) > 1:
                pairs += 1
    return (pairs, ones)

