# ✌️ Two Pair
# Try to fill each of the 4 corner boxes with two different pairs, like 3, 3, 8 and 8 in any
# order. Each box with two different pairs scores 1 primary point. Each box with only one pair, or
# three of a kind, scores 1 secondary point. Four of a kind scores nothing. The board is cut into
# 4 corner boxes of 2×2 cells.

def utility(grid):
    two_pairs = 0
    one_pair = 0
    for cell in grid.cells:
        if cell.row % 2 == 1 or cell.col % 2 == 1:
            continue
        box = [cell, cell.right, cell.down, cell.down.right]
        counts = {}
        for other in box:
            counts[other.value] = counts.get(other.value, 0) + 1
        sizes = sorted(counts.values())
        if sizes == [2, 2]:
            two_pairs += 1
        elif sizes == [1, 1, 2] or sizes == [1, 3]:
            one_pair += 1
    return (two_pairs, one_pair)

